import {prepareAiMoves} from './combat-ai.mjs';
import * as Art from './art.mjs';
import {drawAttack,drawRelease} from './attack-fx.mjs';
import {drawBattleScene,drawCondition} from './battle-scene.mjs';
import {createArena,stepArena,arenaInput,arenaFire,arenaSwap,arenaDodge,AW,AH} from './arena-model.mjs';
import {trainedFighter,addXP} from './training.mjs';
import {moveData,describeMove,STATUS,clamp} from './combat-rules.mjs';
const fmt=n=>Math.ceil(n),ID=(c,id)=>c.g.modeRoot.querySelector('#'+id);
export class ArenaBattle {
 constructor(g){this.g=g;this.active=false;this.rewarded=new Set()}
 startSolo(){if(!this.g.requireStarter())return;const g=this.g,keys=g.state.team,mons=keys.map(k=>trainedFighter(g.dex,g.state,k,{},50)),pool=[3,6,9,25,94,130,65,68,59,143,448,282].filter(id=>g.dex[id]),enemies=Array.from({length:Math.max(1,mons.length)},(_,i)=>{const key=String(pool[(g.state.floor+i)%pool.length]);const mon=trainedFighter(g.dex,{training:{[key]:{xp:125000}},roster:[key]},key,{},50);const utility=g.dex[key].learnset.filter(m=>m.level<=50&&m.status&&(/dance|calm-mind|will-o-wisp|recover|protect|thunder-wave/.test(m.slug)));if(utility.length)mon.moves[3]={...utility[0],left:utility[0].pp};return prepareAiMoves(mon,g.dex)});this.mount(createArena([{pid:'hero',name:g.state.player.name,active:0,mons},{pid:'cpu',name:'Dresseur de l’arène',active:0,mons:enemies}],{theme:g.state.floor%3===0?'moon':'garden',ai:true}),'hero',null)}
 mountNetwork(state,duel){this.mount(state,duel.peer.id,duel);duel.active=true;duel.data={over:false};duel.arenaMode=true}
 mount(state,pid,duel){this.s=structuredClone(state);this.receivedAt=performance.now();this.displayActors=null;this.previousActors=null;this.pid=pid;this.duel=duel;this.guest=!!duel&&!duel.isHost;this.active=true;this.resultShown=false;this.hudMon=null;this.stickID=null;this.keys=new Set();this.input={x:0,y:0};this.aim=null;this.frameTime=performance.now();this.accumulator=0;this.syncAt=0;this.inputAt=0;this.abort?.abort();this.abort=new AbortController();this.g.enterMode('arena');this.g.modeRoot.innerHTML=`<canvas id="arena-canvas" aria-label="Arène Pokémon en temps réel"></canvas><header class="arena-top"><div><small>COMBAT DE DRESSEURS</small><b>Arène 2D <span id="arena-clock"></span></b></div><div><button data-act="arena-help" aria-label="Commandes">?</button><button data-act="arena-pause" id="arena-pause" ${this.guest?'disabled':''}>Ⅱ</button><button data-act="arena-exit">Quitter</button></div></header><div class="arena-health" id="arena-health"></div><div class="arena-radio" id="arena-radio" role="status"></div><div class="arena-dock"><div class="arena-actions" id="arena-actions"></div><div class="arena-reserves" id="arena-reserves"></div><button class="arena-dodge" data-act="arena-dodge">Esquive <b id="arena-dashes">2 / 2</b><small>Espace</small></button></div><div class="arena-stick" id="arena-stick" aria-label="Joystick de déplacement"><i></i></div><div class="arena-pause-layer" id="arena-paused" hidden><small>COMBAT EN PAUSE</small><h2>Prêt à reprendre ?</h2><button class="primary" data-act="arena-pause" ${this.guest?'disabled':''}>Reprendre</button></div><div class="arena-result" id="arena-result" hidden><span class="eyebrow">LE COMBAT EST TERMINÉ</span><h2></h2><p></p><button class="primary" data-act="arena-exit">Retour aux combats</button></div>`;this.canvas=ID(this,'arena-canvas');this.ctx=this.canvas.getContext('2d',{alpha:false});this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(this.g.modeRoot);this.resize();this.bind();Art.preload(this.s.teams.flatMap(t=>t.mons.map(m=>m.key)));this.hud();this.raf=requestAnimationFrame(t=>this.loop(t));this.g.toast('ZQSD / flèches : bouger · 1–4 : attaques · Espace : esquive')}
 get me(){return this.s.teams.find(t=>t.pid===this.pid)}get actor(){return this.s.actors.find(a=>a.pid===this.pid)}get enemy(){return this.s.teams.find(t=>t.pid!==this.pid)}
 resize(){const r=this.g.modeRoot.getBoundingClientRect();this.width=r.width;this.height=r.height;this.canvas.width=Math.round(r.width);this.canvas.height=Math.round(r.height);const dock=this.g.modeRoot.querySelector('.arena-dock')?.getBoundingClientRect().height||180;this.scale=Math.min(r.width/AW,(r.height-125-dock)/AH);this.view={x:(r.width-AW*this.scale)/2,y:125+(r.height-125-dock-AH*this.scale)/2};this.ctx.imageSmoothingEnabled=false}
 world(e){const r=this.canvas.getBoundingClientRect();return{x:clamp((e.clientX-r.left-this.view.x)/this.scale,0,AW),y:clamp((e.clientY-r.top-this.view.y)/this.scale,0,AH)}}
 bind(){const signal=this.abort.signal;document.addEventListener('keydown',e=>{if(!this.active||this.g.modal.open||e.target instanceof HTMLInputElement)return;if(['KeyW','KeyZ','KeyA','KeyQ','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)){e.preventDefault();this.keys.add(e.code)}if(!e.repeat&&/^Digit[1-4]$/.test(e.code)){e.preventDefault();this.action('arena-fire',{slot:+e.code.slice(-1)-1})}if(e.code==='Space'){e.preventDefault();if(!e.repeat)this.action('arena-dodge',{})}if(e.code==='Escape'){e.preventDefault();this.action('arena-pause',{})}if(e.code==='KeyR'&&!e.repeat){const next=this.me.mons.findIndex((m,i)=>i!==this.me.active&&m.hp>0);if(next>=0)this.action('arena-swap',{slot:next})}},{signal});document.addEventListener('keyup',e=>this.keys.delete(e.code),{signal});addEventListener('blur',()=>{this.keys.clear();this.input={x:0,y:0}},{signal});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!this.guest&&!this.s.over){this.s.paused=true;this.sync();this.hud()}},{signal});this.canvas.addEventListener('pointermove',e=>{if(e.pointerType!=='touch'){this.aim=this.world(e);this.aimAt=performance.now()}},{signal});this.canvas.addEventListener('pointerdown',e=>{if(e.button===0){this.aim=this.world(e);this.aimAt=performance.now()}},{signal});const stick=ID(this,'arena-stick');stick.addEventListener('pointerdown',e=>{e.preventDefault();stick.setPointerCapture(e.pointerId);this.stickID=e.pointerId;this.stickCenter=stick.getBoundingClientRect();this.joystick(e)},{signal});stick.addEventListener('pointermove',e=>{if(e.pointerId===this.stickID)this.joystick(e)},{signal});const release=()=>{this.stickID=null;this.input={x:0,y:0};stick.querySelector('i').style.transform='translate(0,0)'};stick.addEventListener('pointerup',release,{signal});stick.addEventListener('pointercancel',release,{signal})}
 joystick(e){const r=this.stickCenter,dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy)||1,ratio=Math.min(1,32/len);this.input={x:dx/32*ratio,y:dy/32*ratio};ID(this,'arena-stick').querySelector('i').style.transform=`translate(${dx*ratio}px,${dy*ratio}px)`}
 sendInput(){const down=(...keys)=>keys.some(k=>this.keys.has(k)),input=this.stickID!==null&&this.stickID!==undefined?this.input:{x:+down('KeyD','ArrowRight')-+down('KeyA','KeyQ','ArrowLeft'),y:+down('KeyS','ArrowDown')-+down('KeyW','KeyZ','ArrowUp')};const enemy=this.s.actors.find(a=>a.pid!==this.pid),aim=this.aim&&performance.now()-this.aimAt<4000?this.aim:{x:enemy.x,y:enemy.y};const packet={...input,aimX:aim.x,aimY:aim.y};if(this.guest)this.duel.conn?.send({type:'arena-input',id:this.s.id,input:packet});else arenaInput(this.s,this.pid,packet)}
 action(act,d={}){if(!this.active)return;if(act==='arena-exit'){this.stop();return}if(act==='arena-help'){this.help();return}if(act==='arena-pause'){if(this.guest||this.s.over)return;this.s.paused=!this.s.paused;this.sync();this.hud();return}this.sendInput();const command=act==='arena-fire'?{kind:'fire',slot:+d.slot}:act==='arena-swap'?{kind:'swap',slot:+d.slot}:act==='arena-dodge'?{kind:'dodge'}:null;if(!command)return;if(this.guest)this.duel.conn?.send({type:'arena-command',id:this.s.id,command});else this.command(this.pid,command)}
 command(pid,c){this.s.chart=this.g.chart;this.s.field.chart=this.g.chart;if(c?.kind==='fire')arenaFire(this.s,pid,c.slot);if(c?.kind==='swap')arenaSwap(this.s,pid,c.slot);if(c?.kind==='dodge')arenaDodge(this.s,pid);delete this.s.chart;delete this.s.field.chart;this.hud();this.sync()}
 receive(packet){if(!this.active||packet.id!==this.s.id)return;if(packet.type==='arena-input'&&!this.guest)arenaInput(this.s,this.duel.conn.peer,packet.input);if(packet.type==='arena-command'&&!this.guest)this.command(this.duel.conn.peer,packet.command);if(packet.type==='arena-state'&&this.guest){this.previousActors=this.displayActors||this.s.actors.map(a=>({...a}));this.receivedAt=performance.now();this.s=packet.state;this.hud();if(this.s.over)this.finish()}}
 sync(){if(this.duel?.isHost&&this.duel.conn?.open)this.duel.conn.send({type:'arena-state',id:this.s.id,state:this.s})}
 loop(t){if(!this.active)return;const delta=Math.min(.2,(t-this.frameTime)/1000);this.frameTime=t;this.accumulator+=delta;if(t-this.inputAt>50){this.inputAt=t;this.sendInput()}if(!this.guest)while(this.accumulator>=.05){stepArena(this.s,.05,this.g.chart);this.accumulator-=.05}else this.accumulator=0;if(t-this.syncAt>100){this.syncAt=t;this.sync();this.hud()}this.draw(t/1000);if(this.s.over)this.finish();this.raf=requestAnimationFrame(t=>this.loop(t))}
 hud(){if(!this.active)return;const me=this.me,m=me.mons[me.active],a=this.actor;ID(this,'arena-clock').textContent=Math.max(0,Math.ceil(this.s.limit-this.s.time))+' s';ID(this,'arena-paused').hidden=!this.s.paused||this.s.over;ID(this,'arena-health').innerHTML=this.s.teams.map(t=>{const mon=t.mons[t.active];return`<section class="${t.pid===this.pid?'mine':'enemy'}"><span>${this.g.escape(t.name)}</span><b>${mon.name} <small>${STATUS[mon.status]||''}</small></b><div><i style="width:${Math.max(0,mon.hp/mon.max*100)}%"></i></div><small>${fmt(mon.hp)} / ${mon.max} PV · ${t.mons.filter(m=>m.hp>0).length} / ${t.mons.length} Pokémon</small></section>`}).join('');const signature=m.key+':'+me.active+':'+m.moves.map(m=>m.id).join(',');if(this.hudMon!==signature){this.hudMon=signature;ID(this,'arena-actions').innerHTML=m.moves.map((raw,i)=>{const move=moveData(raw);return`<button data-act="arena-fire" data-slot="${i}" style="--move:${(Art.COLORS[move.type]||Art.COLORS.normal)[0]}" title="${this.g.escape(describeMove(move))}"><em>${i+1}</em><b>${move.name}</b><small></small><i></i></button>`}).join('');ID(this,'arena-reserves').innerHTML=me.mons.map((mon,i)=>`<button data-act="arena-swap" data-slot="${i}" title="${mon.name}"><img src="${Art.icon(mon.key)}" alt="${mon.name}"><i></i></button>`).join('')}ID(this,'arena-actions').querySelectorAll('button').forEach((b,i)=>{const raw=m.moves[i],cd=a.cooldowns[i];b.disabled=cd>.03||raw.left<=0||this.s.paused||this.s.over;b.querySelector('small').textContent=(cd>.1?cd.toFixed(1)+' s · ':'')+raw.left+'/'+raw.pp+' PP';b.querySelector('i').style.transform=`scaleX(${Math.min(1,cd/5)})`});ID(this,'arena-reserves').querySelectorAll('button').forEach((b,i)=>{b.disabled=i===me.active||me.mons[i].hp<=0||a.swapCooldown>0||this.s.over;b.classList.toggle('selected',i===me.active);b.querySelector('i').style.width=me.mons[i].hp/me.mons[i].max*100+'%'});ID(this,'arena-dashes').textContent=a.dash+' / 2';ID(this,'arena-radio').textContent=this.s.log.at(-1)?.text||'Vise avec la souris · Change de Pokémon avec R'}
 draw(time){const c=this.ctx,s=this.s,reduced=this.g.state.settings.reducedMotion;c.fillStyle='#122b35';c.fillRect(0,0,this.width,this.height);c.save();c.translate(this.view.x,this.view.y);c.scale(this.scale,this.scale);drawBattleScene(c,AW,AH,s.theme,time,{weather:s.field.weather,reducedMotion:reduced});for(const rock of s.cover){if(rock.hp<=0){c.fillStyle='#4b6a60';c.fillRect(rock.x-14,rock.y,8,4);c.fillRect(rock.x+4,rock.y+5,11,4);continue}c.fillStyle='#233d43';c.beginPath();c.ellipse(rock.x,rock.y+15,rock.r*1.3,rock.r*.45,0,0,7);c.fill();c.fillStyle='#9aa68e';c.fillRect(rock.x-rock.r,rock.y-rock.r,rock.r*2,rock.r*1.8);c.fillStyle='#c4c5a6';c.fillRect(rock.x-rock.r,rock.y-rock.r,rock.r*2,6);c.fillStyle='#718575';c.fillRect(rock.x+rock.r-7,rock.y-rock.r,7,rock.r*1.8)}
 this.displayActors=s.actors.map((a,i)=>{const prev=this.previousActors?.[i],ratio=Math.min(1,(performance.now()-this.receivedAt)/100);return this.guest&&prev?{...a,x:prev.x+(a.x-prev.x)*ratio,y:prev.y+(a.y-prev.y)*ratio}:a});for(let i=0;i<2;i++){const a=this.displayActors[i],t=s.teams[i],m=t.mons[t.active],dir=Art.direction(a.aimX-a.x,a.aimY-a.y),moving=Math.abs(a.input.x)+Math.abs(a.input.y)>.1;c.fillStyle='#152d3e77';c.beginPath();c.ellipse(a.x,a.y+22,29,11,0,0,7);c.fill();c.strokeStyle=a.pid===this.pid?'#e6edb3':'#ea9d9e';c.lineWidth=2;c.beginPath();c.ellipse(a.x,a.y+23,31,12,0,0,7);c.stroke();c.globalAlpha=a.invuln>0?.55:1;if(m.hp>0)Art.drawMon(c,m.key,a.x,a.y,128,moving?'Walk':s.time<(a.fireUntil||0)?'Attack':'Idle',dir,time);c.globalAlpha=1;drawCondition(c,m,a.x,a.y,110,time,reduced);c.font='14px PixelLocal';c.textAlign='center';c.lineWidth=4;c.strokeStyle='#12313b';c.strokeText(m.name,a.x,a.y-46);c.fillStyle='#e4edce';c.fillText(m.name,a.x,a.y-46)}
 for(const shot of s.projectiles){const color=(Art.COLORS[shot.move.type]||Art.COLORS.normal)[0];c.save();c.strokeStyle=color;c.fillStyle=color;if(shot.age<shot.delay){const to=shot.kind==='zone'?shot.aim:shot.from;c.setLineDash([5,5]);c.globalAlpha=.45;c.lineWidth=2;c.beginPath();c.arc(to.x,to.y,shot.kind==='zone'?95:26,0,Math.PI*2);c.stroke()}else{c.globalAlpha=.9;c.lineWidth=shot.kind==='wave'?50:7;c.beginPath();c.moveTo(shot.x-shot.dx*24,shot.y-shot.dy*24);c.lineTo(shot.x,shot.y);c.stroke();c.fillStyle='#e9f1c3';c.beginPath();c.arc(shot.x,shot.y,shot.kind==='wave'?18:8,0,Math.PI*2);c.fill()}c.restore()}
 for(const e of s.effects){const age=s.time-e.start;if(e.kind==='attack')drawAttack(c,e.move,e.from,e.to,age,{reducedMotion:reduced});if(e.kind==='release'){drawRelease(c,{x:e.to.x-60,y:e.to.y+70},e.to,age/e.duration,{reducedMotion:reduced})}if(e.kind==='hit'&&e.amount){c.fillStyle='#fff0c3';c.font='bold 20px PixelLocal';c.textAlign='center';c.fillText('−'+e.amount,e.to.x,e.to.y-25-age*35)}}c.restore()}
 help(){const paused=this.s.paused;if(!this.guest){this.s.paused=true;this.sync()}this.g.openModal(`<div class="arena-help"><span class="eyebrow">ARÈNE 2D</span><h2>Bouge, vise, esquive.</h2><p>Flèches ou ZQSD/WASD : déplacements. Souris : viser. Touches 1 à 4 : capacités. Espace : esquive, avec deux charges. R : changer de Pokémon.</p><p>Sur mobile : joystick à gauche, quatre capacités à droite, visée automatique vers l’adversaire. Clique un réserviste pour le faire entrer.</p><p>Les attaques ont des PP, une récupération et une portée. Les piliers bloquent les projectiles et peuvent être détruits. Les zones annoncées au sol peuvent être esquivées. Les types, statuts, talents et changements de Pokémon comptent.</p><button class="primary" data-act="close-modal">C’est parti</button></div>`,{onClose:()=>{if(this.active&&!this.guest){this.s.paused=paused;this.sync();this.hud()}}})}
 finish(){if(this.resultShown)return;this.resultShown=true;const won=this.s.winner===this.pid;if(this.duel)this.duel.data.over=true;if(!this.rewarded.has(this.s.id)){this.rewarded.add(this.s.id);this.g.state.candies++;this.g.state.team.forEach(k=>addXP(this.g.state,k,won?40:20));this.g.save()}ID(this,'arena-result').hidden=false;ID(this,'arena-result').querySelector('h2').textContent=won?'Victoire !':'Bien joué, dresseur.';ID(this,'arena-result').querySelector('p').textContent='+1 bonbon · Expérience gagnée par ton équipe';this.sync()}
 stop(){this.active=false;this.abort?.abort();this.observer?.disconnect();cancelAnimationFrame(this.raf);if(this.duel){this.duel.active=false;this.duel.arenaMode=false;this.duel.clean()}this.resultShown=false;this.g.leaveMode();this.g.route('pvp')}
}
